using System.Collections.Generic;
using System.IO;
using NUnit.Framework;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using EchoMaze.UI;

namespace EchoMaze.Tests
{
    /// <summary>
    /// The scene the game boots into is wired, not just present.
    ///
    /// <c>Boot.unity</c> is generated by <c>Tools/Echo Maze/Build Boot Scene</c>, and twice that produced a
    /// scene that looked right in the editor and shipped nothing: a bootstrap that created a second
    /// <c>Calibration</c> panel on every run (five of them, each folded away, so the duplicate was invisible
    /// until the YAML was counted), and reference fields that serialized as <c>{fileID: 0}</c> because the
    /// object they pointed at was made after the scene was saved. Both are invisible to a human who only
    /// presses Play, and both are one grep away in the saved file — so they are asserted here instead.
    /// </summary>
    public class BootSceneWiringTests
    {
        const string BootScenePath = "Assets/Scenes/Boot.unity";

        static Scene bootScene;
        static bool sceneOpened;

        [OneTimeSetUp]
        public void OpenTheGeneratedMenuScene()
        {
            Assert.IsTrue(File.Exists(BootScenePath),
                          BootScenePath + " is missing: run Tools/Echo Maze/Build Everything first — " +
                          "every scene in this project is generated by that menu item.");

            bootScene = EditorSceneManager.OpenScene(BootScenePath, OpenSceneMode.Additive);
            sceneOpened = true;
        }

        [OneTimeTearDown]
        public void CloseTheMenuScene()
        {
            if (sceneOpened && bootScene.IsValid())
            {
                EditorSceneManager.CloseScene(bootScene, true);
            }
        }

        static int Count<T>() where T : Component
        {
            int n = 0;
            foreach (GameObject root in bootScene.GetRootGameObjects())
            {
                n += root.GetComponentsInChildren<T>(true).Length;
            }

            return n;
        }

        static T Single<T>(out GameObject gameObject) where T : Component
        {
            var found = new List<T>();
            foreach (GameObject root in bootScene.GetRootGameObjects())
            {
                found.AddRange(root.GetComponentsInChildren<T>(true));
            }

            gameObject = found.Count == 1 ? found[0].gameObject : null;
            return found.Count == 0 ? null : found[0];
        }

        static Object Reference(Component owner, string fieldName)
        {
            var so = new SerializedObject(owner);
            SerializedProperty property = so.FindProperty(fieldName);
            Assert.IsNotNull(property, owner.GetType().Name + " has no serialized field named " + fieldName);
            return property.objectReferenceValue;
        }

        [Test]
        public void AGeneratedMenuScene_HasExactlyOneCalibrationPanel()
        {
            // The count first, because the failure is a pile of folded-away panels rather than a missing one,
            // and "is not null" would report the second case while the scene is showing the first.
            Assert.AreEqual(1, Count<CalibrationPanel>(),
                            "the bootstrap adds a calibration page every time it runs instead of finding the " +
                            "one already in the scene; each extra is folded away, so the menu looks fine and the " +
                            "saved scene grows one panel per rebuild");

            CalibrationPanel panel = Single<CalibrationPanel>(out GameObject root);
            Assert.IsNotNull(panel, "the menu scene has no calibration page, so the CALIBRATE button opens nothing");
            Assert.AreEqual("Calibration", root.name);
        }

        [Test]
        public void AGeneratedMenuScene_SerializesTheInputPickerAsRealReferences()
        {
            CalibrationPanel panel = Single<CalibrationPanel>(out _);
            Assert.IsNotNull(panel);

            // {fileID: 0} here means the bootstrap wired the button into an object that was never put in the
            // saved scene — the page opens, the picker is dead, and the player has no way off a monitor device.
            Assert.IsInstanceOf<Button>(Reference(panel, "deviceButton"),
                                        "the input picker button is not in the saved scene");
            Assert.IsInstanceOf<Text>(Reference(panel, "deviceLabel"),
                                      "the line that names what the game is hearing is not in the saved scene");
            Assert.IsInstanceOf<VoiceCalibration>(Reference(panel, "calibration"),
                                                  "the page has no calibration object to measure against");
        }

        [Test]
        public void AGeneratedMenuScene_KeepsTheCalibrationPageInsideTheMenuCanvas()
        {
            CalibrationPanel panel = Single<CalibrationPanel>(out GameObject root);
            Assert.IsNotNull(panel);

            MainMenu menu = Single<MainMenu>(out GameObject menuRoot);
            Assert.IsNotNull(menu, "the menu scene has no MainMenu to press PLAY on");
            Assert.AreSame(menuRoot.transform, root.transform.parent,
                           "the calibration page is a sibling of the canvas instead of a child of it, so the " +
                           "raycaster on the menu cannot reach its buttons");
            Assert.IsFalse(root.activeSelf,
                           "the calibration page ships unfolded, so the game opens on a meter instead of a title");
        }
    }
}
